<?php
namespace App\Http\Controllers;
use App\Models\Announcement; use App\Models\OrganizationMembership; use App\Services\AnnouncementService; use Illuminate\Http\Request;
class AnnouncementController extends Controller { public function __construct(private AnnouncementService $announcements){} private function actor(Request $r):OrganizationMembership{return $r->attributes->get('currentMembership');} public function index(Request $r){$page=$this->announcements->visible($this->actor($r))->paginate(50);return $r->expectsJson()?response()->json($page):view('workspace.announcements.index',['page'=>$page]);} public function store(Request $r){$a=$this->announcements->create($this->actor($r),$r->all());return $r->expectsJson()?response()->json(['data'=>$a],201):redirect()->route('announcements.index')->with('success','Announcement saved.');} public function publish(Request $r,int $announcement){$a=Announcement::where('organization_id',$this->actor($r)->organization_id)->findOrFail($announcement);$published=$this->announcements->publish($this->actor($r),$a);return $r->expectsJson()?response()->json(['data'=>$published]):redirect()->route('announcements.index')->with('success','Announcement published.');}}
